274	\title{The phenomenological cornucopia of SU(3) exotica}
275	
276	\preprint{UCI-HEP-TR-2021-26}
277	
278	\author{Linda M. Carpenter}
279	\email{lmc@physics.osu.edu}
280	\author{Taylor Murphy}
281	\email{murphy.1573@osu.edu}
282	\affiliation{Department of Physics, The Ohio State University\\ 191 W. Woodruff Ave., Columbus, OH 43212, U.S.A.}
283	\author{Tim M. P. Tait}
